fn add_initialization_input_conditions(
    field: &Field,
    requires: &mut Vec<Expr>,
    init_value: Expr,
    param_value: Expr,
) {
    match &field.stype {
        ShardableType::StorageOption(_)
        | ShardableType::StorageMap(_, _)
        | ShardableType::StorageIMap(_, _) => {
            requires.push(mk_eq(param_value.span(), &param_value, &init_value));
        }
        _ => {
            panic!("this should implement each case enabled by get_init_param_input_type");
        }
    }
}

fn get_init_param_output_type(sm: &SM, field: &Field) -> Option<Type> {
    match &field.stype {
        ShardableType::Variable(_) => Some(field_token_type(&sm, field)),
        ShardableType::Constant(_) => None, // constants handled separately
        ShardableType::NotTokenized(_) => None, // no tokens
        ShardableType::Count | ShardableType::PersistentCount => Some(field_token_type(&sm, field)),
        ShardableType::Multiset(_)
        | ShardableType::Option(_)
        | ShardableType::PersistentOption(_)
        | ShardableType::Bool
        | ShardableType::PersistentBool
        | ShardableType::Set(_)
        | ShardableType::ISet(_)
        | ShardableType::PersistentSet(_)
        | ShardableType::PersistentISet(_)
        | ShardableType::Map(..)
        | ShardableType::IMap(..)
        | ShardableType::PersistentMap(..)
        | ShardableType::PersistentIMap(..) => Some(field_token_collection_type(sm, field)),

        ShardableType::StorageOption(_) => None, // no output tokens for storage
        ShardableType::StorageMap(_, _) => None,
        ShardableType::StorageIMap(_, _) => None,
    }
}

fn add_initialization_output_conditions(
    sm: &SM,
    field: &Field,
    ensures: &mut Vec<Expr>,
    inst_eq_enss: &mut Vec<Expr>,
    init_value: Expr,
    inst_value: Expr,
    param_value: Expr,
) {
    match &field.stype {
        ShardableType::Variable(_) => {
            inst_eq_enss.push(Expr::Verbatim(quote_vstd! { vstd =>
                #vstd::prelude::equal((#param_value).instance_id(), #inst_value)
            }));
            ensures.push(Expr::Verbatim(quote_vstd! { vstd =>
                #vstd::prelude::equal(#param_value.value(), #init_value)
            }));
        }
        ShardableType::Count | ShardableType::PersistentCount => {
            inst_eq_enss.push(Expr::Verbatim(quote_vstd! { vstd =>
                #vstd::prelude::equal((#param_value).instance_id(), #inst_value)
            }));
            ensures.push(Expr::Verbatim(quote_vstd! { vstd =>
                #vstd::prelude::equal(#param_value.count(), #init_value)
            }));
        }
        ShardableType::Option(_)
        | ShardableType::PersistentOption(_)
        | ShardableType::Bool
        | ShardableType::PersistentBool
        | ShardableType::Set(_)
        | ShardableType::ISet(_)
        | ShardableType::PersistentSet(_)
        | ShardableType::PersistentISet(_)
        | ShardableType::Map(_, _)
        | ShardableType::IMap(_, _)
        | ShardableType::PersistentMap(_, _)
        | ShardableType::PersistentIMap(_, _)
        | ShardableType::Multiset(_) => {
            ensures.push(relation_for_collection_of_internal_tokens(
                sm,
                field,
                param_value,
                init_value,
                inst_value,
                true,
                field.name.span(),
            ));
        }
        _ => {
            panic!("this should implement each case enabled by get_init_param_output_type");
        }
    }
}

fn relation_for_collection_of_internal_tokens(
    _sm: &SM,
    field: &Field,
    param_value: Expr,
    given_value: Expr,
    inst_value: Expr,
    output: bool,
    span: Span,
) -> Expr {
    // For output tokens, we allow the user to assume a slightly stronger condition about the data.
    // For input tokens, we require the user to prove a slightly weaker one.
    let strict = output;

    match &field.stype {
        ShardableType::Option(_) | ShardableType::PersistentOption(_) => {
            let fncall = if strict {
                quote_spanned_vstd! { vstd, span => #vstd::tokens::option_value_eq_option_token }
            } else {
                quote_spanned_vstd! { vstd, span => #vstd::tokens::option_value_le_option_token }
            };
            Expr::Verbatim(quote_spanned! { span =>
                #fncall(#given_value, #param_value, #inst_value)
            })
        }
        ShardableType::Bool | ShardableType::PersistentBool => {
            let fncall = if strict {
                quote_spanned_vstd! { vstd, span => #vstd::tokens::bool_value_eq_option_token }
            } else {
                quote_spanned_vstd! { vstd, span => #vstd::tokens::bool_value_le_option_token }
            };
            Expr::Verbatim(quote_spanned! { span =>
                #fncall(#given_value, #param_value, #inst_value)
            })
        }
        ShardableType::Set(_) | ShardableType::PersistentSet(_) => {
            let fncall = if strict {
                quote_spanned_vstd! { vstd, span => #vstd::prelude::equal }
            } else {
                quote_spanned_vstd! { vstd, span => #vstd::set::Set::spec_le }
            };
            Expr::Verbatim(quote_spanned_vstd! { vstd, span =>
                #fncall(#given_value, (#param_value).set())
                  && #vstd::prelude::equal((#param_value).instance_id(), #inst_value)
            })
        }
        ShardableType::ISet(_) | ShardableType::PersistentISet(_) => {
            let fncall = if strict {
                quote_spanned_vstd! { vstd, span => #vstd::prelude::equal }
            } else {
                quote_spanned_vstd! { vstd, span => #vstd::iset::ISet::spec_le }
            };
            Expr::Verbatim(quote_spanned_vstd! { vstd, span =>
                #fncall(#given_value, (#param_value).set())
                  && #vstd::prelude::equal((#param_value).instance_id(), #inst_value)
            })
        }
        ShardableType::Map(_, _) | ShardableType::PersistentMap(_, _) => {
            let fncall = if strict {
                quote_spanned_vstd! { vstd, span => #vstd::prelude::equal }
            } else {
                quote_spanned_vstd! { vstd, span => #vstd::map::Map::spec_le }
            };
            Expr::Verbatim(quote_spanned_vstd! { vstd, span =>
                #fncall(#given_value, (#param_value).map())
                  && #vstd::prelude::equal((#param_value).instance_id(), #inst_value)
            })
        }
        ShardableType::IMap(_, _) | ShardableType::PersistentIMap(_, _) => {
            let fncall = if strict {
                quote_spanned_vstd! { vstd, span => #vstd::prelude::equal }
            } else {
                quote_spanned_vstd! { vstd, span => #vstd::imap::IMap::spec_le }
            };
            Expr::Verbatim(quote_spanned_vstd! { vstd, span =>
                #fncall(#given_value, (#param_value).map())
                  && #vstd::prelude::equal((#param_value).instance_id(), #inst_value)
            })
        }
        ShardableType::Multiset(_) => {
            let fncall = if strict {
                quote_spanned_vstd! { vstd, span => #vstd::prelude::equal }
            } else {
                quote_spanned_vstd! { vstd, span => #vstd::multiset::Multiset::spec_le }
